/**
 * Post-build script — fixes the wrangler.json generated by @cloudflare/vite-plugin.
 *
 * For Cloudflare Pages SSR, the wrangler.json in dist/client/ should NOT have:
 * - main (Pages doesn't support this field)
 * - pages_build_output_dir (redundant, already in root wrangler.toml)
 * 
 * We keep only: compatibility settings, bindings (D1, R2, etc.)
 * The SSR entry point is handled via _worker.js in the output directory.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const file = join(__dirname, "..", "dist", "client", "wrangler.json");

if (!existsSync(file)) {
  console.error("❌ dist/client/wrangler.json not found — build may have failed.");
  process.exit(1);
}

const config = JSON.parse(readFileSync(file, "utf-8"));

// Fields not supported by Cloudflare Pages configuration
const invalidForPages = [
  // Pages doesn't support these
  "main",                    // Pages error: "does not support 'main'"
  "pages_build_output_dir",  // Redundant, already in root wrangler.toml
  "assets",                  // Pages error: "does not support assets"
  "triggers",                // Pages error: "expected crons array"
  "build",
  // Unknown/future fields that cause parse errors
  "definedEnvironments",
  "ai_search_namespaces",
  "ai_search",
  "secrets_store_secrets",
  "artifacts",
  "unsafe_hello_world",
  "flagship",
  "worker_loaders",
  "ratelimits",
  "vpc_services",
  "vpc_networks",
  "python_modules",
  "legacy_env",
  "userConfigPath",
  "jsx_factory",
  "jsx_fragment",
  "rules",
  "cloudchamber",
  "logfwdr",
  "topLevelName",
  "configPath",
];

for (const key of invalidForPages) {
  delete config[key];
}

// Remove unknown dev sub-fields
if (config.dev) {
  const validDevFields = ["ip", "port", "local_protocol", "upstream_protocol"];
  for (const key of Object.keys(config.dev)) {
    if (!validDevFields.includes(key)) {
      delete config.dev[key];
    }
  }
  if (Object.keys(config.dev).length === 0) {
    delete config.dev;
  }
}

// Remove empty arrays/objects that Pages doesn't need
const emptyArrayFields = [
  "workflows", "migrations", "kv_namespaces", "send_email",
  "r2_buckets", "vectorize", "hyperdrive", "services",
  "analytics_engine_datasets", "dispatch_namespaces",
  "mtls_certificates", "pipelines",
];
for (const key of emptyArrayFields) {
  const val = config[key];
  if (val !== undefined) {
    const isEmpty = Array.isArray(val)
      ? val.length === 0
      : typeof val === "object" && Object.keys(val).length === 0;
    if (isEmpty) delete config[key];
  }
}

// Remove durable_objects if it has no bindings
if (config.durable_objects?.bindings?.length === 0) {
  delete config.durable_objects;
}

// Always remove dev block — not needed for Pages deploy
delete config.dev;

// Remove empty queues
if (config.queues) {
  const noProducers = !config.queues.producers?.length;
  const noConsumers = !config.queues.consumers?.length;
  if (noProducers && noConsumers) delete config.queues;
}

// Remove empty vars
if (config.vars && Object.keys(config.vars).length === 0) {
  delete config.vars;
}

// Ensure D1 database binding has the correct database_id
const D1_DATABASE_ID = "1daf6984-59c5-402e-b3fc-5ff438034c94";
const D1_DATABASE_NAME = "driveschool-pro";
const D1_BINDING = "DB";

if (!config.d1_databases || !Array.isArray(config.d1_databases)) {
  config.d1_databases = [];
}
const existingBinding = config.d1_databases.find((b) => b.binding === D1_BINDING);
if (existingBinding) {
  existingBinding.database_id = D1_DATABASE_ID;
  existingBinding.database_name = D1_DATABASE_NAME;
} else {
  config.d1_databases.push({
    binding: D1_BINDING,
    database_name: D1_DATABASE_NAME,
    database_id: D1_DATABASE_ID,
  });
}

writeFileSync(file, JSON.stringify(config, null, 2));
console.log("✅ dist/client/wrangler.json cleaned for Cloudflare Pages deploy.");
console.log("   Remaining fields:", Object.keys(config).join(", "));
console.log("   ✓ Removed 'main' and 'pages_build_output_dir' (not supported by Pages)");


